		expect(findings.remoteTarballDependencies).toEqual([]);
		/** A version-range lockfile of the old shape reads the same way. */
		expect(
			readLockfileFindings('package-lock.json', {
				lockfileVersion: 1,
				dependencies: { 'file-saver': { version: FILE_SAVER_SPEC } },
